import pickletools, glob, os

def extract(path):
    ops=list(pickletools.genops(open(path,'rb').read()))
    res={}
    for i,(op,arg,pos) in enumerate(ops):
        if op.name in ('SHORT_BINUNICODE','BINUNICODE','UNICODE') and arg in ('id','val_accuracy'):
            # next meaningful op after memoize perhaps
            j=i+1
            while j<len(ops) and ops[j][0].name=='MEMOIZE': j+=1
            op2,arg2,pos2=ops[j]
            # for id, skip to unicode
            if arg=='id':
                if op2.name in ('SHORT_BINUNICODE','BINUNICODE','UNICODE'):
                    res['id']=arg2
            elif arg=='val_accuracy':
                if op2.name in ('BINFLOAT','FLOAT'):
                    res['val_accuracy']=arg2
                elif op2.name.startswith('BININT') or op2.name=='INT':
                    res['val_accuracy']=arg2
    return res
rows=[]
for p in sorted(glob.glob('/tmp/models/*.pkl')):
    d=extract(p); rows.append(d)
    print(os.path.basename(p), d)
print('\nLeaderboard:')
for d in sorted(rows, key=lambda x:x['val_accuracy'], reverse=True):
    print(d['id'], f"{d['val_accuracy']:.4f}")
